-- Actual authored steer input and immutable controls. Legacy Redis has no receipt.
CREATE TABLE steer_authored_origins(id TEXT PRIMARY KEY,steer_id TEXT NOT NULL,tenant_id BIGINT NOT NULL,session_id TEXT NOT NULL,owner_id TEXT NOT NULL,owner_revision BIGINT NOT NULL,origin_run_message_id TEXT NOT NULL,origin_run_generation_id TEXT NOT NULL,origin_run_request_id TEXT NOT NULL,actor TEXT NOT NULL,body_digest TEXT NOT NULL,canonical_digest TEXT NOT NULL,source_lineage TEXT NOT NULL,execution_context TEXT NOT NULL,agent_id TEXT NOT NULL,agent_tenant_id BIGINT NOT NULL,input_body TEXT NOT NULL,created_at_ms BIGINT NOT NULL,UNIQUE(tenant_id,session_id,steer_id));
CREATE TABLE steer_control_admissions(id TEXT PRIMARY KEY,origin_id TEXT NOT NULL REFERENCES steer_authored_origins(id),tenant_id BIGINT NOT NULL,session_id TEXT NOT NULL,steer_id TEXT NOT NULL,previous_head_id TEXT NOT NULL,revision BIGINT NOT NULL,operation TEXT NOT NULL,run_message_id TEXT NOT NULL,run_generation_id TEXT NOT NULL,run_request_id TEXT NOT NULL,delivery TEXT NOT NULL,consumed BOOLEAN NOT NULL,discarded BOOLEAN NOT NULL,deleted BOOLEAN NOT NULL,user_message_id TEXT NOT NULL,created_at_ms BIGINT NOT NULL);
CREATE TABLE steer_control_heads(origin_id TEXT PRIMARY KEY REFERENCES steer_authored_origins(id),head_id TEXT NOT NULL REFERENCES steer_control_admissions(id),revision BIGINT NOT NULL);
CREATE TABLE steer_consumption_origins(id TEXT PRIMARY KEY,origin_id TEXT NOT NULL REFERENCES steer_authored_origins(id),selection_manifest TEXT NOT NULL,previous_head_id TEXT NOT NULL,result_head_id TEXT NOT NULL,user_message_id TEXT NOT NULL UNIQUE,user_generation_id TEXT NOT NULL,user_admission_id TEXT NOT NULL,user_body_digest TEXT NOT NULL,session_id TEXT NOT NULL,run_message_id TEXT NOT NULL,run_generation_id TEXT NOT NULL,run_request_id TEXT NOT NULL,previous_membership_revision BIGINT NOT NULL,result_membership_revision BIGINT NOT NULL);
CREATE TRIGGER steer_authored_origins_immutable_update BEFORE UPDATE ON steer_authored_origins BEGIN SELECT RAISE(ABORT,'immutable original steer material'); END;
CREATE TRIGGER steer_authored_origins_immutable_delete BEFORE DELETE ON steer_authored_origins BEGIN SELECT RAISE(ABORT,'immutable original steer material'); END;
CREATE TRIGGER steer_control_admissions_immutable_update BEFORE UPDATE ON steer_control_admissions BEGIN SELECT RAISE(ABORT,'immutable original steer material'); END;
CREATE TRIGGER steer_control_admissions_immutable_delete BEFORE DELETE ON steer_control_admissions BEGIN SELECT RAISE(ABORT,'immutable original steer material'); END;
CREATE TRIGGER steer_consumption_origins_immutable_update BEFORE UPDATE ON steer_consumption_origins BEGIN SELECT RAISE(ABORT,'immutable original steer material'); END;
CREATE TRIGGER steer_consumption_origins_immutable_delete BEFORE DELETE ON steer_consumption_origins BEGIN SELECT RAISE(ABORT,'immutable original steer material'); END;
CREATE TABLE steer_control_versions(origin_id TEXT PRIMARY KEY,revision BIGINT NOT NULL);
CREATE TRIGGER steer_head_insert AFTER INSERT ON steer_control_heads BEGIN INSERT INTO steer_control_versions VALUES(NEW.origin_id,1) ON CONFLICT(origin_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER steer_head_update AFTER UPDATE ON steer_control_heads BEGIN INSERT INTO steer_control_versions VALUES(NEW.origin_id,1) ON CONFLICT(origin_id) DO UPDATE SET revision=revision+1; END;
CREATE TABLE message_completion_input_manifests(assistant_admission_id TEXT PRIMARY KEY REFERENCES message_material_admissions(id),recipe TEXT NOT NULL CHECK(recipe='history-initial-and-consumed-steer-v1'),parent_manifest TEXT NOT NULL CHECK(length(parent_manifest)<=262144),manifest_digest TEXT NOT NULL CHECK(length(manifest_digest)=64));
CREATE TRIGGER message_completion_input_manifests_immutable_update BEFORE UPDATE ON message_completion_input_manifests BEGIN SELECT RAISE(ABORT,'immutable actual completion inputs'); END;
CREATE TRIGGER message_completion_input_manifests_immutable_delete BEFORE DELETE ON message_completion_input_manifests BEGIN SELECT RAISE(ABORT,'immutable actual completion inputs'); END;
